You assess retrieved reference tests for unit-test generation.
A generator must write a Hardhat (ethers 6, Mocha/Chai) unit-test suite for the TARGET Solidity contract below.
It receives example tests retrieved from a corpus of OTHER contracts. Such examples are never written for the target:
a different contract name is expected and is NOT a reason for a low rating. Judge only their value as a template.

Rate the RETRIEVED TEST:
2 = directly adaptable: it exercises a behaviour that the target also implements (same kind of operation, state change,
    access rule or revert condition); its setup, calls, assertions or revert checks could be reused after renaming.
1 = partially useful: it shows a generic testing pattern applicable to the target (e.g., access-control revert, event
    assertion, time manipulation, balance change, deployment with constructor arguments), but the specific behaviour it
    tests does not exist in the target.
0 = not useful: neither its behaviour nor its testing pattern applies to the target.

Give a reason of at most 30 words, then the rating.

TARGET CONTRACT:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Counter {
    uint256 public count;
    address public immutable owner;

    constructor() { owner = msg.sender; }

    function increment() external { count += 1; }
    function decrement() external {
        require(count > 0, "underflow");
        count -= 1;
    }
    function reset() external {
        require(msg.sender == owner, "not owner");
        count = 0;
    }
}

RETRIEVED TEST:
// corpus-v2 pair enerpay-remittance--edgadafi (escrow-conditional-payments, complex)
// EnerpayRemittance.test.js: EnerpayRemittance > Owner functions > Should revert owner functions if not owner
const { expect } = require("chai");
const { ethers } = require("hardhat");
let enerpayRemittance;
let cUSD;
let owner;
let treasury;
let sender;
let beneficiary;
let otherAccount;
const INITIAL_BALANCE = ethers.parseEther("10000");
// beforeEach of suite "EnerpayRemittance"
beforeEach(async function () {
    [owner, treasury, sender, beneficiary, otherAccount] =
      await ethers.getSigners();

    // Deploy mock ERC20 token (cUSD)
    const MockERC20 = await ethers.getContractFactory("MockERC20");
    cUSD = await MockERC20.deploy("Celo Dollar", "cUSD", INITIAL_BALANCE);
    await cUSD.waitForDeployment();

    // Deploy EnerpayRemittance
    const EnerpayRemittance = await ethers.getContractFactory(
      "EnerpayRemittance"
    );
    enerpayRemittance = await EnerpayRemittance.deploy(
      await cUSD.getAddress(),
      treasury.address
    );
    await enerpayRemittance.waitForDeployment();

    // Fund sender account
    await cUSD.transfer(sender.address, ethers.parseEther("1000"));
  })
it("Should revert owner functions if not owner", async function () {
      await expect(
        enerpayRemittance.connect(otherAccount).setPlatformFee(200)
      ).to.be.revertedWithCustomError(enerpayRemittance, "OwnableUnauthorizedAccount");

      await expect(
        enerpayRemittance
          .connect(otherAccount)
          .setTreasuryAddress(otherAccount.address)
      ).to.be.revertedWithCustomError(enerpayRemittance, "OwnableUnauthorizedAccount");

      await expect(
        enerpayRemittance
          .connect(otherAccount)
          .emergencyWithdraw(ethers.parseEther("100"), otherAccount.address)
      ).to.be.revertedWithCustomError(enerpayRemittance, "OwnableUnauthorizedAccount");
    })


